// Local appearance settings and station controls. No production integrations.
let brandDraft=null,brandRead=0,brandBusy=false;
const brandDefaults={name:'Reuse Canada',primary:'#246244',accent:'#d4ef9d',logo:''};
function brandValue(){return {...brandDefaults,...state.branding}}
function inkOn(hex){const rgb=hex.match(/\w\w/g).map(v=>parseInt(v,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722>.179?'#13231b':'#ffffff'}
function applyBrand(b=brandValue()){
 const root=document.documentElement;root.style.setProperty('--green',b.primary);root.style.setProperty('--green-dark','color-mix(in srgb, '+b.primary+' 55%, #101b20)');root.style.setProperty('--lime',b.accent);root.style.setProperty('--brand-ink',inkOn(b.primary));root.style.setProperty('--accent-ink',inkOn(b.accent));
 document.querySelector('.breadcrumb').innerHTML=esc(b.name)+' <span>/</span> Yard operations';document.querySelector('footer>span').textContent=b.name+' · Scale House';document.title='Scale House · '+b.name;const logo=document.querySelector('.brand');logo.setAttribute('aria-label',b.name+' home');logo.innerHTML=b.logo?'<img src="'+esc(b.logo)+'" alt="'+esc(b.name)+' logo">':esc(b.name.trim().slice(0,1)||'S')+'<span>↗</span>';
 if($('brand-preview'))$('brand-preview').innerHTML=(b.logo?'<img src="'+esc(b.logo)+'" alt="Logo preview">':'<span class="brand-monogram">'+esc(b.name.slice(0,1))+'</span>')+'<div><strong>'+esc(b.name||'Your yard')+'</strong><p>Your yard. Your identity.</p></div><button class="button primary" type="button" data-brand-demo>Sample action</button>';
}
function brandingSettings(){brandDraft=brandValue();brandBusy=false;modal('Make it yours','<p class="modal-intro">Give your station its own identity. Changes preview instantly; save when it feels right.</p><form id="branding-form"><div id="brand-preview" class="brand-preview"></div><label class="field">Business name<input name="brandName" maxlength="70" required value="'+esc(brandDraft.name)+'"></label><div class="brand-presets">'+[['Forest','#246244','#d4ef9d'],['Ocean','#245b81','#a9e5ef'],['Clay','#8b4936','#f3c7a0'],['Midnight','#44386d','#ded2ff']].map(([n,p,a])=>'<button type="button" class="button" data-palette="'+p+','+a+'"><i style="background:'+p+'"></i>'+n+'</button>').join('')+'</div><div class="form-grid"><label class="field">Main colour<input type="color" name="primary" value="'+brandDraft.primary+'"></label><label class="field">Accent colour<input type="color" name="accent" value="'+brandDraft.accent+'"></label></div><label class="field">Upload your logo<input id="brand-logo" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG or WebP under 20 MB. Resized for this browser preview; transparent PNG works best.</small></label><button class="text-button" type="button" data-brand-remove>Remove logo</button><p id="brand-error" role="alert"></p><div class="modal-actions"><button type="button" class="button" data-brand-reset>Restore default look</button><button type="button" class="button" data-action="close">Cancel</button><button id="brand-save" type="submit" class="button primary">Save appearance</button></div></form>','BRANDING & APPEARANCE');applyBrand(brandDraft)}
function renderCockpit(){
 const live=state.settings.mode==='live',a=autoState(),pending=a.visits.filter(v=>v.status!=='completed').length,issues=a.incidents.filter(i=>!i.resolved).length;
 document.querySelector('.auto-entry').hidden=!live;
 document.querySelector('.agent-summary').innerHTML='<div class="pilot-head"><div class="pilot-orb '+(live?'running':'')+'">✦</div><div><span class="eyebrow">STATION CO-PILOT</span><h3>'+(live?'Watching your yard':'You’re in control')+'</h3></div><span class="pill '+(live?'good':'')+'">'+(live?'Auto':'Manual')+'</span></div><div class="pilot-switch" aria-label="Station mode"><button aria-pressed="'+!live+'" data-station-mode="off">Manual</button><button aria-pressed="'+live+'" data-station-mode="live">Auto mode</button></div><p id="agent-summary-text">'+(live?'Driver check-in, paired weights and billing—all in one visit.':'Capture, assign and weigh out with the original operator workflow. Unattended actions are paused.')+'</p><div class="pilot-path">'+['Check in','Weigh','Bill'].map((n,i)=>'<button data-pilot-step="'+i+'"><span>0'+(i+1)+'</span>'+n+'</button>').join('')+'</div><div class="pilot-metrics"><button data-auto="open"><strong>'+pending+'</strong><span>Active visits</span></button><button data-auto="open"><strong>'+issues+'</strong><span>Need review</span></button></div><div class="pilot-health"><span><i class="dot '+(state.connected?'green':'')+'"></i>Scale '+(state.connected?'ready':'offline')+'</span><button class="text-button" data-auto="emergency">'+(a.emergency.email?'Emergency contact ✓':'Set emergency contact →')+'</button></div><button class="button '+(live?'primary':'')+' pilot-open" '+(live?'data-auto="driver"':'data-action="capture"')+'>'+(live?'Try driver check-in →':'Capture a weight →')+'</button><button class="text-button" data-setting="agent">Advanced automation settings →</button>';
 applyBrand();
}
function requireAuto(){if(state.settings.mode==='live')return true;toast('Auto mode is off. Use the manual weighing station, or enable Auto mode.');return false}
function stationMode(mode){state.settings.mode=mode;save();toast(mode==='live'?'Auto mode enabled. Unattended demo is available.':'Manual mode enabled. Unattended visits are paused and kept for later.');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.pilotHome){close();go('workspace');return}if(b.dataset.stationMode)return stationMode(b.dataset.stationMode);if(b.dataset.pilotStep!==undefined){const live=state.settings.mode==='live';const steps=[['Driver check-in',live?'Drivers upload a licence for each visit, confirm extracted details and choose their material.':'Use New ticket and assign the customer, driver, plate and material.'],['Paired weighing',live?'Matching camera plates and stable weights link arrival and departure. Exceptions pause the visit for remote review.':'Capture an arrival weight, then choose the right yard ticket to weigh out.'],['Billing',live?'Completed walk-ins receive a payment-link preview; approved accounts receive an invoice preview.':'Review the receipt and collect payment or leave it unpaid for follow-up.']];modal(steps[b.dataset.pilotStep][0],'<p class="modal-intro">'+steps[b.dataset.pilotStep][1]+'</p>'+actions('<button class="button primary" '+(live?'data-auto="open"':'data-pilot-home="true"')+'>Open workspace →</button>'),'HOW IT WORKS');return}if(b.dataset.palette&&brandDraft){[brandDraft.primary,brandDraft.accent]=b.dataset.palette.split(',');document.querySelector('[name=primary]').value=brandDraft.primary;document.querySelector('[name=accent]').value=brandDraft.accent;applyBrand(brandDraft)}if(b.hasAttribute('data-brand-remove')&&brandDraft){brandRead++;brandBusy=false;brandDraft.logo='';$('brand-save').disabled=false;$('brand-logo').value='';applyBrand(brandDraft)}if(b.hasAttribute('data-brand-reset')){brandRead++;brandDraft={...brandDefaults};brandingResetFields();applyBrand(brandDraft)}if(b.hasAttribute('data-brand-demo'))toast('This is your button style preview.');});
function brandingResetFields(){brandBusy=false;document.querySelector('[name=brandName]').value=brandDraft.name;document.querySelector('[name=primary]').value=brandDraft.primary;document.querySelector('[name=accent]').value=brandDraft.accent;$('brand-save').disabled=false;$('brand-logo').value='';}
document.addEventListener('input',e=>{if(!e.target.closest('#branding-form')||!brandDraft)return;const n=e.target.name;if(n==='brandName')brandDraft.name=e.target.value;if(n==='primary'||n==='accent')brandDraft[n]=e.target.value;applyBrand(brandDraft)});
document.addEventListener('change',e=>{if(e.target.id!=='brand-logo'||!brandDraft)return;const f=e.target.files[0],version=++brandRead;brandBusy=false;$('brand-save').disabled=false;if(!f)return;if(f.size>=20*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)){$('brand-error').textContent='Choose a PNG, JPG or WebP under 20 MB.';return}brandBusy=true;$('brand-save').disabled=true;const reader=new FileReader();const fail=()=>{if(version!==brandRead||!brandDraft)return;brandBusy=false;$('brand-save').disabled=false;$('brand-error').textContent='This picture could not be read. Please try another.';};reader.onerror=fail;reader.onload=()=>{const img=new Image();img.onerror=fail;img.onload=()=>{if(version!==brandRead||!brandDraft)return;const ratio=Math.min(1,400/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);brandDraft.logo=canvas.toDataURL('image/png');brandBusy=false;$('brand-save').disabled=false;$('brand-error').textContent='Logo ready.';applyBrand(brandDraft)};img.src=reader.result;};reader.readAsDataURL(f)});
document.addEventListener('submit',e=>{if(e.target.id!=='branding-form')return;e.preventDefault();if(brandBusy||!brandDraft)return;brandDraft.name=brandDraft.name.trim();if(!brandDraft.name)return;state.branding={...brandDraft};brandDraft=null;save();close();toast('Your station’s appearance has been saved.');});
document.getElementById('modal').addEventListener('close',()=>{if(brandDraft){brandDraft=null;brandRead++;brandBusy=false;applyBrand()}});
